import{z as l,x as s,o as i,c as m,q as o,j as A,D as t,d as e,s as B,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"潜在结果","description":"","frontmatter":{"title":"潜在结果","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/potential-outcomes.md","filePath":"econ/potential-outcomes.md","lastUpdated":1791413859000}'),d={name:"econ/potential-outcomes.md"};function D(p,a,T,u,h,c){const n=s("Mermaid");return i(),m("div",null,[a[2]||(a[2]=o('<h1 id="潜在结果" tabindex="-1">潜在结果 <a class="header-anchor" href="#潜在结果" aria-label="Permalink to &quot;潜在结果&quot;">​</a></h1><div class="epigraph"><p>因果不是回归系数的别名：每个人有两套潜在结果，观测到的永远只是其中一套；平均处理效应是对不可观测对照的陈述。</p><footer>—— Neyman, On the Application of Probability Theory to Agricultural Experiments, 1923；Rubin, Estimating Causal Effects of Treatments in Randomized and Nonrandomized Studies, J. Educ. Psychol. 1974</footer></div><p><a href="/econ/gibbard-satterthwaite">上一课</a>把无转移时的策略证明收到不可能定理。本课起计量经济学：先给出<strong>潜在结果</strong>，后课的 OLS、工具、双重差分才有对象。定价核、限价簿协议不在本课重写。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>看见「接受培训的人后来工资更高」，可以把相关写成 \\(\\mathrm{Cov}(Y,D)\\gt 0\\)。Holland（1986）强调：因果问的是同一人在 \\(D=1\\) 与 \\(D=0\\) 下的 \\(Y_i(1)-Y_i(0)\\)，其中一套永远缺失。<span class="marginnote">把每个人想象成手里有两张底牌：「接受培训时的工资」和「没接受培训时的工资」。上帝两张都看得见，现实里你只能翻开一张——另一张被「当时的选择」永远盖住。因果推断的全部功夫，就是用各种设计去估出那堆看不见底牌的平均值；而两个看得见的平均一减，混进来的往往是「谁会去翻哪张牌」本身。</span>缺口不是再讲工资方程从哪来，而是把「若他当时没接受处理」写成合法对象，并声明平均掉个体缺失之后还剩什么。</p><p>单位 \\(i\\)、二值处理 \\(D_i\\in\\{0,1\\}\\)，潜在结果 \\(Y_i(1),Y_i(0)\\)，观测</p> \\[Y_i = D_i Y_i(1)+(1-D_i)Y_i(0). \\]<p>个体处理效应 \\(\\tau_i=Y_i(1)-Y_i(0)\\) 不可识别。平均处理效应 \\(\\mathrm{ATE}=\\mathbb{E}[\\tau_i]\\)、处理组平均 \\(\\mathrm{ATT}=\\mathbb{E}[\\tau_i\\mid D_i=1]\\) 是后课估计量要对准的参数。没有这套语言，遗漏变量、选择偏差、LATE 会对不准同一句话。</p><p><span class="marginnote">SUTVA：无干扰（\\(i\\) 的潜在结果不依赖别人的 \\(D\\)）与处理无隐藏版本。聚类、一般均衡、溢出一旦重要，本课的二值潜在结果就要扩状态，不能假装还是 \\(\\tau_i\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>随机化使 \\(D\\perp(Y(1),Y(0))\\)，于是 \\(\\mathbb{E}[Y\\mid D=1]-\\mathbb{E}[Y\\mid D=0]=\\mathrm{ATE}\\)。<span class="marginnote">用数字看选择偏差怎么混进来：假设能力强的人更愿意培训。处理组「没培训也能挣 3000」，培训后挣 5000；对照组没培训只挣 2000。朴素差分 \\(=5000-2000=3000\\)，但真实效应只有 \\(5000-3000=2000\\)——多出的 1000 是「处理组底子好」送的，不是培训的功劳。随机化的意义正是把这种「底子差」在概率上抹平。</span>观测研究把这句话换成可检验的替代：条件独立（给定 \\(X\\) 后 \\(D\\) 与潜在结果独立）、或后课的工具、断点、平行趋势。Imbens 与 Rubin 的教科书把设计放在估计之前：先说赋值机制，再谈回归。</p>',11)),(i(),A(r,null,{default:t(()=>[B(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20POT%5B%22%E6%BD%9C%E5%9C%A8%E7%BB%93%E6%9E%9C%20Y(1)%2C%20Y(0)%22%5D%20--%3E%20MISS%5B%22%E5%8F%AA%E8%A7%82%E6%B5%8B%E5%88%B0%E5%85%B6%E4%B8%AD%E4%B8%80%E5%A5%97%22%5D%0A%20%20MISS%20--%3E%20ATE%5B%22ATE%20%2F%20ATT%20%E6%98%AF%E5%AF%B9%E7%BC%BA%E5%A4%B1%E7%9A%84%E5%B9%B3%E5%9D%87%22%5D%0A%20%20RAND%5B%22%E9%9A%8F%E6%9C%BA%E5%8C%96%22%5D%20--%3E%20ID%5B%22D%20%E7%8B%AC%E7%AB%8B%E4%BA%8E%E6%BD%9C%E5%9C%A8%E7%BB%93%E6%9E%9C%22%5D%0A%20%20ID%20--%3E%20ATE%0A%20%20OBS%5B%22%E8%A7%82%E6%B5%8B%E7%A0%94%E7%A9%B6%22%5D%20--%3E%20SUB%5B%22%E7%94%A8%20X%E3%80%81%E5%B7%A5%E5%85%B7%E3%80%81%E6%96%AD%E7%82%B9%E6%9B%BF%E4%BB%A3%E9%9A%8F%E6%9C%BA%E5%8C%96%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"回归可以是估计 ATE 的一种算法，不是因果的定义。把 \\(\\beta\\) 叫「效应」之前，必须指出它对应 ATE、ATT 还是加权混合。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是反事实对照。科学实验用随机化制造对照；社会科学用制度、资格规则、外生冲击去逼近。选择偏差是 \\(\\mathbb{E}[Y(0)\\mid D=1]\\neq\\mathbb{E}[Y(0)\\mid D=0]\\)：处理组即使未处理，基线也不同。条件独立把选择收到可观测 \\(X\\) 里；收不干净就是后课遗漏变量。",-1)),a[6]||(a[6]=E("p",null,[e("与"),E("a",{href:"/econ/revealed-preference"},"显示偏好"),e("对照：那里从选择恢复排序；这里从赋值机制恢复对照。两边都禁止把「看见的差」直接叫结构。卢卡斯批判说政策规则一变简化式就变；潜在结果把「政策」写成对 \\(D\\) 的干预，要求干预下 \\(Y(d)\\) 稳定——这是稳定性假设，不是免费午餐。"),E("span",{class:"marginnote"},"「稳定性」翻译成大白话：你的潜在结果只取决于你自己有没有被处理，与「谁被处理、处理怎么执行」无关。疫苗是直观反例：身边接种的人越多，你不接种也不感染的几率越高——你的 \\(Y(0)\\) 随别人的选择变，SUTVA 破掉，简单对照就不再干净，需要把溢出写进模型。")],-1)),(i(),A(r,null,{default:t(()=>[B(n,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%A4%84%E7%90%86%E7%BB%84%E8%A7%82%E6%B5%8B%E5%9D%87%E5%80%BC%20E%5BY%7CD%3D1%5D%5D%20--%3E%20DIF%5B%E6%9C%B4%E7%B4%A0%E5%B7%AE%E5%88%86%22%5D%0A%20%20C%5B%22%E5%AF%B9%E7%85%A7%E7%BB%84%E8%A7%82%E6%B5%8B%E5%9D%87%E5%80%BC%20E%5BY%7CD%3D0%5D%22%5D%20--%3E%20DIF%0A%20%20DIF%20--%3E%20SPLIT%5B%22%E6%8B%86%E5%BC%80%20%3D%20ATE%20%2B%20%E9%80%89%E6%8B%A9%E5%81%8F%E5%B7%AE%22%5D%0A%20%20SB%5B%22%E9%80%89%E6%8B%A9%E5%81%8F%E5%B7%AE%20%3D%20E%5BY(0)%7CD%3D1%5D%20%E2%88%92%20E%5BY(0)%7CD%3D0%5D%22%5D%20--%3E%20SPLIT%0A%20%20SPLIT%20--%3E%20R1%5B%22%E9%9A%8F%E6%9C%BA%E5%8C%96%EF%BC%9A%E9%80%89%E6%8B%A9%E5%81%8F%E5%B7%AE%E4%B8%BA%200%EF%BC%8C%E5%B7%AE%E5%88%86%E5%8D%B3%20ATE%22%5D%0A%20%20SPLIT%20--%3E%20R2%5B%22%E8%87%AA%E9%80%89%E6%8B%A9%EF%BC%9A%E4%B8%8D%E4%B8%BA%200%EF%BC%8C%E5%B7%AE%E5%88%86%E8%99%9A%E9%AB%98%E6%88%96%E8%99%9A%E4%BD%8E%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">Holland：因果效应是相对处理的，没有「绝对原因」。没有对照的处理，没有定义清楚的效应。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估一个培训项目，不把 ATE 写成「经济学的唯一目标」：政策常常要 ATT 或条件效应。一般均衡、市场价格反馈、溢出，破坏 SUTVA；那是后课结构模型与<a href="/econ/heterogeneous-effects">异质处理效应</a>的缺口。量化栏的事件研究与因子回归有另一套对象，不在此重写。也不要把潜在结果与结构方程对立成教派：Rubin 给赋值，Marschak–Heckman 给均衡决策，后课会接。</p><p>后课默认：谈到「效应」时，先指潜在结果的哪一个平均；随机化是黄金标准，其余设计是替代假设。OLS 下一课只是在线性条件下估计某种加权平均，不是新的因果定义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>因果参数是潜在结果的对照；观测方程把其中一套藏起来。</li><li>ATE / ATT 是对缺失的平均；个体 \\(\\tau_i\\) 一般不可得。</li><li>随机化识别 ATE；观测研究必须另写赋值假设。</li><li>SUTVA 排除干扰与隐藏版本；一破就要扩状态。</li><li>出处：Neyman 1923；Rubin, <em>J. Educ. Psychol.</em> 1974；Holland, <em>JASA</em> 1986；Imbens and Rubin, <em>Causal Inference</em> 2015。</li></ul>',6))])}const C=l(d,[["render",D]]);export{b as __pageData,C as default};
